mapper.sql:
WHERE AT.CMPNY_CD = #{gvCmpnyCd}
  AND AT.DEL_YN = 'N'
  /* 집계 모수: 입실한 출결만(미입실 제외) */
  AND AT.ENTRY_AT IS NOT NULL
  /* 스코프 필터: master/safe(companyWide=true)는 회사 전체, 그 외는 자기 사업장(세션 기준)만 */

    AND S.SITE_CD = #{scopeSiteCd}

  /* 검색 사업장은 추가 필터일 뿐(companyWide 아니면 위 강제와 AND 되어 스코프 우회 불가) */

    AND S.SITE_CD = #{siteCd}

  /* 기간 = 이수일(STATUS_UPDATED_AT). NULL 상태시각은 기간 지정 시 제외 */

    AND DATE(AT.STATUS_UPDATED_AT) >= #{startDate}


    AND DATE(AT.STATUS_UPDATED_AT) <= #{endDate}

  /* 이름/사번 검색(정규/일용 유형별 컬럼 선택) */

    AND (
         (CASE WHEN AT.USER_TYPE_CD = 'REGULAR' THEN RU.USER_NM ELSE DU.USER_NM END) LIKE CONCAT('%', #{searchKeyword}, '%')
      OR (CASE WHEN AT.USER_TYPE_CD = 'REGULAR' THEN RU.USER_ID ELSE DU.USER_ID END) LIKE CONCAT('%', #{searchKeyword}, '%')
    )

mapper.select:
/* Tbm03Mapper.selectUserProgressUser */
SELECT DU.USER_CD AS userCd , 'DAILY' AS userTypeCd , DU.USER_NM AS userNm , '일용직' AS employmentTypeNm , DU.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , NULL AS deptNm FROM TB_DAILY_USER DU LEFT OUTER JOIN TB_SITE ST ON ( DU.CMPNY_CD = ST.CMPNY_CD AND DU.SITE_CD = ST.SITE_CD ) WHERE DU.CMPNY_CD = #{gvCmpnyCd} AND DU.USER_CD = #{userCd}
SELECT RU.USER_CD AS userCd , 'REGULAR' AS userTypeCd , RU.USER_NM AS userNm , ET.SYST_VAL_D_NM AS employmentTypeNm , RU.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , ND.NODE_NM AS deptNm FROM TB_USER RU LEFT OUTER JOIN TB_SITE ST ON ( RU.CMPNY_CD = ST.CMPNY_CD AND RU.SITE_CD = ST.SITE_CD ) LEFT OUTER JOIN TB_SITE_NODE ND ON ( RU.CMPNY_CD = ND.CMPNY_CD AND RU.SITE_CD = ND.SITE_CD AND RU.NODE_CD = ND.NODE_CD ) LEFT OUTER JOIN ( SELECT D.SYST_VAL_D_CD, D.SYST_VAL_D_NM FROM TB_SYST_VAL_D D WHERE D.SYST_VAL_CD = 'SYS041' AND D.USE_YN = 'Y' ) ET ON ( RU.EMPLOYMENT_TYPE = ET.SYST_VAL_D_CD ) WHERE RU.CMPNY_CD = #{gvCmpnyCd} AND RU.USER_CD = #{userCd}

mapper.sql:
WHERE AT.CMPNY_CD = #{gvCmpnyCd}
  AND AT.USER_TYPE_CD = #{userTypeCd}
  AND AT.USER_CD = #{userCd}
  AND AT.DEL_YN = 'N'
  /* 집계 모수: 입실한 출결만 */
  AND AT.ENTRY_AT IS NOT NULL
  /* 이수상태 필터: 미이수는 입실 미완료(NULL or NOT_COMPLETED) 포함 */

    AND AT.COMPLETION_STATUS_CD = 'COMPLETED'


    AND (AT.COMPLETION_STATUS_CD IS NULL OR AT.COMPLETION_STATUS_CD = 'NOT_COMPLETED')

  /* 기간 = 이수일(STATUS_UPDATED_AT). NULL 상태시각은 기간 지정 시 제외 */

    AND DATE(AT.STATUS_UPDATED_AT) >= #{startDate}


    AND DATE(AT.STATUS_UPDATED_AT) <= #{endDate}
